#define BUF_SZ 4096
char custom_buffer[BUF_SZ];
FILE *stream = stdout; // Must be called before first I/O

// 1. Full Buffering (_IOFBF): Use custom_buffer
int status_full = setvbuf(
    stream, custom_buffer, _IOFBF, BUF_SZ
);

// 2. Line Buffering (_IOLBF): System allocated buffer (NULL)
int status_line = setvbuf(
    stream, NULL, _IOLBF, BUF_SZ
);

// 3. No Buffering (_IONBF): Size is ignored (0)
int status_none = setvbuf(
    stream, NULL, _IONBF, 0
);
